#!/usr/bin/env bash
# Image parity: proves the image built by the legacy Jenkins command and the image
# built by the GitHub Actions path (Buildx + GHA cache) are functionally identical.
#
# Gating checks (any difference fails the job):
#   1. runtime-config      User, Env, Entrypoint, Cmd, WorkingDir, ExposedPorts, Labels, Healthcheck
#   2. filesystem-content  every file in the flattened image: path, mode, uid:gid, size, sha256
#   3. sbom-packages       package list (type, name, version) generated by Syft for both images
#
# Informational only:
#   4. layer-digests       uncompressed layer digests (diff_ids). These can legitimately
#                          differ between builders because tar headers are produced by
#                          different code paths even when file contents are identical.
#
# Not compared (expected to differ): image ID, manifest digest, "Created" timestamp.
#
# Usage: compare-images.sh <legacy-image-ref> <gha-image-ref> <report.md> [syft-binary]
set -euo pipefail

legacy=${1:?legacy image ref required}
gha=${2:?github actions image ref required}
report=${3:?report path required}
syft=${4:-syft}
here=$(cd "$(dirname "$0")" && pwd)
workdir=$(mktemp -d)
status=0

runtime_config() {
  docker image inspect "$1" | jq -S '.[0].Config | {
    User, WorkingDir, Entrypoint, Cmd, ExposedPorts, Healthcheck, Labels,
    Env: ((.Env // []) | sort)
  }'
}

layers() { docker image inspect "$1" | jq -r '.[0].RootFS.Layers[]'; }

filesystem_manifest() {
  # Flatten the image with `docker export` and hash every entry.
  local cid
  cid=$(docker create "$1")
  docker export "$cid" | python3 "$here/fs-manifest.py"
  docker rm "$cid" > /dev/null
}

packages() {
  "$syft" scan "docker:$1" -o json -q \
    | jq -r '.artifacts[] | "\(.type)\t\(.name)\t\(.version)"' | LC_ALL=C sort
}

runtime_config "$legacy" > "$workdir/legacy-runtime-config"
runtime_config "$gha" > "$workdir/gha-runtime-config"
filesystem_manifest "$legacy" > "$workdir/legacy-filesystem-content"
filesystem_manifest "$gha" > "$workdir/gha-filesystem-content"
packages "$legacy" > "$workdir/legacy-sbom-packages"
packages "$gha" > "$workdir/gha-sbom-packages"
layers "$legacy" > "$workdir/legacy-layer-digests"
layers "$gha" > "$workdir/gha-layer-digests"

count() { wc -l < "$1" | tr -d ' '; }

row() { # name legacy-detail gha-detail gating(yes/no)
  local name=$1
  if diff -u "$workdir/legacy-$name" "$workdir/gha-$name" > "$workdir/$name.diff"; then
    printf '| %s | %s | %s | :white_check_mark: identical |\n' "$name" "$2" "$3"
  elif [ "$4" = "yes" ]; then
    printf '| %s | %s | %s | :x: different |\n' "$name" "$2" "$3"
    status=1
  else
    printf '| %s | %s | %s | :information_source: different (informational) |\n' "$name" "$2" "$3"
  fi
}

summary() { jq -r '"user \(.User), cmd \(.Cmd | join(" "))"' "$1"; }

{
  echo "### Image parity (Jenkins \`docker build\` vs GitHub Actions Buildx)"
  echo
  echo "| Check | Jenkins path | GitHub Actions path | Result |"
  echo "| --- | --- | --- | --- |"
  row runtime-config "$(summary "$workdir/legacy-runtime-config")" "$(summary "$workdir/gha-runtime-config")" yes
  row filesystem-content "$(count "$workdir/legacy-filesystem-content") entries" "$(count "$workdir/gha-filesystem-content") entries" yes
  row sbom-packages "$(count "$workdir/legacy-sbom-packages") packages" "$(count "$workdir/gha-sbom-packages") packages" yes
  row layer-digests "$(count "$workdir/legacy-layer-digests") layers" "$(count "$workdir/gha-layer-digests") layers" no
  echo
  for name in runtime-config filesystem-content sbom-packages layer-digests; do
    if [ -s "$workdir/$name.diff" ]; then
      echo "<details><summary>${name} diff</summary>"
      echo
      echo '```diff'
      head -n 200 "$workdir/$name.diff"
      echo '```'
      echo "</details>"
      echo
    fi
  done
  echo "<details><summary>SBOM packages (both images)</summary>"
  echo
  echo '```text'
  cat "$workdir/gha-sbom-packages"
  echo '```'
  echo "</details>"
  echo
} > "$workdir/section.md"

cat "$workdir/section.md" >> "$report"
cat "$workdir/section.md"

mkdir -p "$(dirname "$report")/evidence"
cp "$workdir"/legacy-* "$workdir"/gha-* "$(dirname "$report")/evidence/"

if [ ! -s "$workdir/legacy-sbom-packages" ] || [ ! -s "$workdir/legacy-filesystem-content" ]; then
  echo "Empty SBOM or filesystem manifest for the legacy image - refusing to call that parity." | tee -a "$report"
  status=1
fi
exit "$status"
